<?php
use GhoroaHat\Rewards\{DB,Settings,Membership,Referral,Wallet,Orders};
ob_start();global $wpdb,$ghr_ref_count;$ghr_ref_count=0;$old=Settings::all();$run='links'.bin2hex(random_bytes(5));
function ref_check($a,$b,$message){global $ghr_ref_count;++$ghr_ref_count;if($a!==$b){throw new RuntimeException($message.': '.var_export($a,true).' != '.var_export($b,true));}echo "PASS $message\n";}
function ref_member($name){$u=wp_insert_user(array('user_login'=>$name,'user_email'=>$name.'@example.org','user_pass'=>wp_generate_password()));Membership::enroll($u);DB::update(DB::table('memberships'),array('status'=>'active','email_verified_at'=>DB::now(),'activated_at'=>DB::now()),array('user_id'=>$u));return $u;}
try{
$a=ref_member($run.'a');$b=ref_member($run.'b');$c=ref_member($run.'c');$ma=Membership::get($a);$mb=Membership::get($b);wp_set_current_user(0);unset($_COOKIE['ghr_ref']);$_SERVER['REMOTE_ADDR']='192.0.2.8';$_SERVER['HTTP_USER_AGENT']=$run;
Settings::save(array('require_tracking_consent'=>true,'referral_model'=>'last','repeat_referrals'=>true,'referral_approval'=>false,'guest_referrals'=>false,'excluded_products'=>array(),'excluded_categories'=>array()));
Referral::track($ma['referral_code']);ref_check(Referral::current(),null,'No persistent attribution before required consent');add_filter('ghr_tracking_consent','__return_true');Referral::track($ma['referral_code']);ref_check((int)Referral::current()['referrer_id'],$a,'Valid referral sets signed attribution');$saved=$_COOKIE['ghr_ref'];$_COOKIE['ghr_ref']=substr($saved,0,-1).('a'===substr($saved,-1)?'b':'a');ref_check(Referral::current(),null,'Tampered cookie rejected');$_COOKIE['ghr_ref']=$saved;
Referral::track('INVALID');ref_check((int)Referral::current()['referrer_id'],$a,'Invalid click cannot replace valid attribution');Referral::track($mb['referral_code']);ref_check((int)Referral::current()['referrer_id'],$b,'Last valid click wins');Settings::save(array('referral_model'=>'first'));Referral::track($ma['referral_code']);ref_check((int)Referral::current()['referrer_id'],$b,'First-click policy retains valid attribution');
ref_check(Wallet::account($b,'referral')['posted'],0,'Cookies and visits alone never issue commission');
$p=new WC_Product_Simple();$p->set_name('Referral fixture');$p->set_regular_price('1000');$p->set_tax_status('none');$p->save();$o=wc_create_order(array('customer_id'=>$c));$o->set_billing_email(get_userdata($c)->user_email);$o->add_product($p,1);Referral::attach($o);$o->calculate_totals();$o->update_status('completed');Orders::reconcile($o->get_id());ref_check(Wallet::account($b,'referral')['posted'],2000,'Completed attributed order earns exact commission');
$stats=Referral::stats($b);ref_check(isset($stats['activity'][0]['buyer_id']),false,'Referral activity contains no buyer identity');ref_check(isset($stats['activity'][0]['order_id']),false,'Public referrer activity uses opaque conversion reference');
Settings::save(array('guest_referrals'=>true));$guest=wc_create_order();$guest->set_billing_email($run.'guest@example.org');$guest->add_product($p,1);Referral::attach($guest);$guest->calculate_totals();$guest->update_status('completed');Orders::reconcile($guest->get_id());ref_check(Wallet::account($b,'referral')['posted'],4000,'Configured guest purchases qualify without creating a member');ref_check($guest->get_customer_id(),0,'Guest account identity unchanged');
Settings::save(array('repeat_referrals'=>false));$repeat=wc_create_order(array('customer_id'=>$c));$repeat->set_billing_email(get_userdata($c)->user_email);$repeat->add_product($p,1);Referral::attach($repeat);$repeat->calculate_totals();$repeat->update_status('completed');Orders::reconcile($repeat->get_id());ref_check(Wallet::account($b,'referral')['posted'],4000,'First-purchase-only policy rejects repeat customer order');
$fraud=wc_create_order();$fraud->set_billing_email(get_userdata($b)->user_email);$fraud->add_product($p,1);Referral::attach($fraud);$fraud->calculate_totals();$fraud->update_status('completed');Orders::reconcile($fraud->get_id());ref_check(Wallet::account($b,'referral')['posted'],4000,'Matching referrer identity is held for review');
remove_filter('ghr_tracking_consent','__return_true');echo "REFERRAL PASS: $ghr_ref_count assertions\n";
}finally{update_option('ghr_settings',$old,false);ob_end_flush();}
